class StudentScreen extends StatefulWidget{const StudentScreen({super.key});@override State<StudentScreen>createState()=>_StudentScreenState();}
class _StudentScreenState extends State<StudentScreen>{ApiClient? _client;late Future<_StudentData> _future;@override void initState(){super.initState();_future=_load();}Future<_StudentData>_load()async{_client??=await AuthenticatedClient.create();final r=StudentRepository(_client!);final p=await r.profile();final stats=await r.stats();return _StudentData(p,stats);}Future<void>_reload()async{setState(()=>_future=_load());await _future;}@override void dispose(){_client?.dispose();super.dispose();}
Future<void>_logout()async{final storage=await AuthStorage.create();final token=await storage.accessToken;if(token?.isNotEmpty==true){try{final c=await AuthenticatedClient.create();await c.postJson('/api/v1/auth/logout');c.dispose();}catch(_){}}await storage.clear();if(mounted)context.go('/login');}
