Text('تسجيل الخروج'))]);}));}
}
class _StudentData{const _StudentData(this.profile,this.stats);final StudentProfile profile;final Map<String,dynamic>stats;}
class _Pill extends StatelessWidget{const _Pill(this.text);final String text;@override Widget build(BuildContext c)=>Container(padding:const EdgeInsets.symmetric(horizontal:12,vertical:5),decoration:BoxDecoration(color:c.colors.surfaceContainerHigh,borderRadius:BorderRadius.circular(14),border:Border.all(color:c.colors.outline)),child:Text(text,style:TextStyle(fontSize:10,color:c.colors.onSurfaceVariant,fontWeight:FontWeight.w700)));}
class _Stat extends StatelessWidget{const _Stat(this.label,this.value);final String label,value;@override Widget build(BuildContext c)=>Container(padding:const EdgeInsets.symmetric(vertical:10),decoration:BoxDecoration(color:c.colors.surfaceContainerHigh,borderRadius:BorderRadius.circular(12)),child:Column(children:[Text(value,maxLines:1,overflow:TextOverflow.ellipsis,style:TextStyle(color:c.colors.primary,fontWeight:FontWeight.w900,fontSize:13)),const SizedBox(height:2),Text(label,style:TextStyle(fontSize:9,color:c.colors.onSurfaceVariant))]));}
class _Action extends StatelessWidget{const _Action(this.label,this.icon,this.onTap);final String label;final IconData icon;final VoidCallback onTap;@override Widget build(BuildContext c)=>InkWell(onTap:onTap,borderRadius:BorderRadius.circular(13),child:Container(height:62,decoration:BoxDecoration(color:c.colors.surface,borderRadius:BorderRadius.circular(13),border:Border.all(color:c.colors.outline)),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(icon,size:21,color:c.colors.primary),const SizedBox(height:4),Text(label,style:const TextStyle(fontSize:9.5,fontWeight:FontWeight.w800))])));}
